type Tree = { kind: "leaf" } | { kind: "inner"; left: Tree; right: Tree };
function depth(t: Tree): number {
  return t.kind === "leaf" ? 0 : 1 + Math.max(depth(t.left), depth(t.right));
}
const t: Tree = {
  kind: "inner",
  left: { kind: "leaf" },
  right: { kind: "inner", left: { kind: "leaf" }, right: { kind: "leaf" } },
};
console.log(depth(t));

type Circle = { radius: number };
type Square = { side: number };
function area(s: Circle | Square): number {
  return "radius" in s ? Math.round(Math.PI * s.radius ** 2) : s.side ** 2;
}
console.log(area({ radius: 1 }), area({ side: 3 }));

type Box = { label: string | null };
function size(b: Box): number {
  if (b.label === null) {
    return 0;
  }
  const read = () => b.label.length;
  return read();
}

function maxBy<T>(items: readonly T[], score: (item: T) => number): T | undefined {
  let best: T | undefined = undefined;
  let bestScore = -Infinity;
  for (const item of items) {
    const s = score(item);
    if (s > bestScore) {
      best = item;
      bestScore = s;
    }
  }
  return best;
}
console.log(maxBy(["pear", "fig", "banana"], (w) => w.length), maxBy<string>([], (w) => w.length));

